#!/usr/bin/env python3
"""
SEO-AD AutoPilot Extension Installer
Usage:
  cd /Users/Zhuanz/Desktop/SEO_AD_BOT
  python3 install_extensions.py
"""
import os, base64, zlib, pathlib, sys

FILES = {'ad_platforms/header_bidding.py': '', 'agents/aio_optimizer.py': '', 'agents/competitor_analyst.py': '', 'agents/rank_tracker.py': '', 'patches/APPLY_PATCHES.sh': '', 'skills/aio_optimizer.py': '', 'skills/competitor_analysis.py': '', 'skills/content_decay.py': '', 'skills/crux_rum.py': '', 'skills/header_bidding.py': '', 'skills/rank_tracking.py': '', 'utils/llm_router.py': ''}

def d(s):
    return zlib.decompress(base64.b64decode(s)).decode('utf-8')

def main():
    root = pathlib.Path(os.getcwd())
    app  = root / 'apps' / 'api' / 'seo_ad_autopilot'
    if not (app / 'agents' / 'base.py').exists():
        print(f'ERROR: Run from SEO_AD_BOT project root.')
        print(f'Expected: {app}/agents/base.py')
        sys.exit(1)

    print('SEO-AD AutoPilot — Extension Installer')
    print('=' * 45)

    for rel, enc in FILES.items():
        if rel.endswith('.sh'):
            continue
        p = app / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(d(enc), encoding='utf-8')
        print(f'  wrote  {rel}')

    # patch agents/base.py
    bp = app / 'agents' / 'base.py'
    c  = bp.read_text()
    if 'AIO_OPTIMIZER' not in c:
        c = c.replace(
            '    MODERATOR = "moderator"',
            '    MODERATOR = "moderator"\n    AIO_OPTIMIZER = "aio_optimizer"\n    RANK_TRACKER = "rank_tracker"\n    COMPETITOR_ANALYST = "competitor_analyst"',
            1
        )
        bp.write_text(c)
        print('  patched agents/base.py (AgentRole)')

    # patch agents/__init__.py
    ai = app / 'agents' / '__init__.py'
    c  = ai.read_text()
    if 'AIOOptimizerAgent' not in c:
        c += '\nfrom .aio_optimizer import AIOOptimizerAgent\nfrom .rank_tracker import RankTrackerAgent\nfrom .competitor_analyst import CompetitorAnalystAgent\n'
        ai.write_text(c)
        print('  patched agents/__init__.py')

    # patch skills/__init__.py
    si = app / 'skills' / '__init__.py'
    c  = si.read_text()
    if 'LLMTxtGeneratorSkill' not in c:
        c += '\nfrom .aio_optimizer import LLMTxtGeneratorSkill, EEATEnhancerSkill, AIOCitationTrackerSkill\nfrom .rank_tracking import RankSnapshotSkill, SERPFeatureTrackerSkill\nfrom .competitor_analysis import CompetitorKeywordGapSkill, ContentGapAnalysisSkill\nfrom .content_decay import ContentDecayDetectorSkill\nfrom .crux_rum import CrUXCollectorSkill, RUMSnippetInjectorSkill\nfrom .header_bidding import HeaderBiddingConfigGeneratorSkill, FloorPriceOptimizerSkill, AdRefreshStrategySkill\n'
        si.write_text(c)
        print('  patched skills/__init__.py')

    # patch ad_platforms/__init__.py
    ai2 = app / 'ad_platforms' / '__init__.py'
    c   = ai2.read_text()
    if 'PrebidHeaderBiddingPlatform' not in c:
        c = 'from .header_bidding import PrebidHeaderBiddingPlatform\n' + c
        c = c.replace(
            '    return registry',
            '    from .header_bidding import PrebidHeaderBiddingPlatform\n    registry.register(PrebidHeaderBiddingPlatform())\n\n    return registry',
            1
        )
        ai2.write_text(c)
        print('  patched ad_platforms/__init__.py')

    # create utils/__init__.py
    ud = app / 'utils'
    ud.mkdir(exist_ok=True)
    ui = ud / '__init__.py'
    if not ui.exists():
        ui.write_text("from .llm_router import LLMCostRouter, get_router, MODEL_CATALOG, TASK_COMPLEXITY_MAP\n__all__ = ['LLMCostRouter','get_router','MODEL_CATALOG','TASK_COMPLEXITY_MAP']\n")
        print('  created utils/__init__.py')

    print()
    print('Done!  3 Agents | 9 Skills | 1 AdPlatform | LLM Router')

if __name__ == '__main__':
    main()
